<!-- Twin Peeks — Spot the Difference. All art is drawn procedurally on canvas, -->
<!-- all sounds are synthesized with WebAudio. No external assets, no network. -->
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Twin Peeks — Spot the Difference</title>
<link rel="stylesheet" href="./style.css">
</head>
<body>
<div id="app">
  <header id="hud">
    <div class="hud-left">
      <span class="logo">🔍 Twin Peeks</span>
      <span class="scene-name" id="sceneName">Sunny Garden</span>
    </div>
    <div class="hud-mid">
      <span class="pill remaining" id="remainingPill">10 remaining</span>
      <span class="pill found" id="foundPill">0 found</span>
      <span class="pill timer" id="timerPill">3:00</span>
    </div>
    <div class="hud-right">
      <span class="pill score" id="scorePill">Score 0</span>
      <button class="hud-btn" id="hintBtn" type="button" title="Hint (H)">💡 Hint</button>
      <button class="hud-btn" id="soundBtn" type="button" title="Sound (M)">🔊</button>
    </div>
  </header>

  <div id="stage">
    <canvas id="game" width="1280" height="660" aria-label="Spot the difference: two near-identical pictures side by side"></canvas>

    <div class="overlay" id="titleScreen">
      <div class="card">
        <h1>🔍 Twin Peeks</h1>
        <p class="tagline">Spot the Difference</p>
        <p class="howto">Two pictures look the same — but they are not.
          <b>Click every difference</b> you can find, in either picture.
          Each scene hides 8–10 differences and the clock is ticking.</p>
        <ul class="scenes">
          <li><b>1 · Sunny Garden</b> — 10 differences · 3:00</li>
          <li><b>2 · Cozy Kitchen</b> — 9 differences · 2:30</li>
          <li><b>3 · Sunny Beach</b> — 10 differences · 2:00</li>
        </ul>
        <button class="big-btn" id="startBtn" type="button">▶ Start playing</button>
        <p class="keys">Mouse: click a difference &nbsp;·&nbsp; <b>H</b> hint &nbsp;·&nbsp; <b>R</b> restart scene &nbsp;·&nbsp; <b>1 / 2 / 3</b> jump to a scene &nbsp;·&nbsp; <b>M</b> sound on/off</p>
      </div>
    </div>

    <div class="overlay hidden" id="sceneScreen">
      <div class="card small">
        <h2 id="sceneTitle">Scene complete!</h2>
        <p class="scene-stats" id="sceneStats"></p>
        <button class="big-btn" id="nextBtn" type="button">Next scene ▶</button>
      </div>
    </div>

    <div class="overlay hidden" id="winScreen">
      <div class="card">
        <h1>🏆 You found them all!</h1>
        <p class="tagline">Every difference in all three scenes — sharp eyes!</p>
        <p class="scene-stats" id="winStats"></p>
        <button class="big-btn" id="againBtn" type="button">↻ Play again</button>
        <p class="keys">Tip: press <b>R</b> any time to restart a scene, <b>H</b> for a hint.</p>
      </div>
    </div>

    <div class="overlay hidden" id="timeScreen">
      <div class="card small">
        <h2>⏰ Time's up!</h2>
        <p class="scene-stats" id="timeStats"></p>
        <button class="big-btn" id="retryBtn" type="button">↻ Try this scene again</button>
      </div>
    </div>
  </div>

  <footer id="helpbar">
    <span>Click a difference in either picture — a golden ring marks it.</span>
    <span class="right">H hint (−25) · R restart · 1/2/3 scene · M sound</span>
  </footer>
</div>
<p id="status" role="status" aria-live="polite"></p>
<script type="module" src="./src/main.js"></script>
</body>
</html>
