export function sun(ctx, x, y, r, withRays) {
  if (withRays) {
    ctx.strokeStyle = '#ffb62e';
    ctx.lineWidth = 6;
    ctx.lineCap = 'round';
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a) * (r + 8), y + Math.sin(a) * (r + 8));
      ctx.lineTo(x + Math.cos(a) * (r + 22), y + Math.sin(a) * (r + 22));
      ctx.stroke();
